1	package net.officefloor.hq.app.rate;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.Comparator;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Objects;
12	import java.util.Optional;
13	import net.officefloor.hq.app.Audit;
14	import net.officefloor.hq.app.rollup.RollupService;
15	import net.officefloor.hq.app.sheet.SheetNotFoundException;
16	import net.officefloor.hq.app.sheet.SheetRepository;
17	import org.springframework.dao.DataIntegrityViolationException;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
22	@Service
23	public class RateService {
24	
25	    private final RateRepository rates;
26	    private final RateLogRepository logs;
27	    private final SheetRepository sheets;
28	    private final Audit audit;
29	    private final RollupService rollup;
30	
31	    public RateService(RateRepository rates, RateLogRepository logs, SheetRepository sheets, Audit audit,
32	            RollupService rollup) {
33	        this.rates = rates;
34	        this.logs = logs;
35	        this.sheets = sheets;
36	        this.audit = audit;
37	        this.rollup = rollup;
38	    }
39	
40	    public List<Rate> list(String sheetId) {
41	        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
42	    }
43	
44	    /**
45	     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
46	     * undated rate counting as from the beginning of time. Empty when the date is before every rate, or
47	     * after that rate's to-date.
48	     */
49	    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
50	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
51	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
52	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
53	                .filter(r -> r.appliesOn(date));
54	    }
55	
56	    /**
57	     * The grade's rate percent in force on the date as the rates stood at the end of {@code asOf}: each from-date's
58	     * last setting made while the sheet's today was on or before it (a rate set before settings were logged counts as
59	     * it is now). Empty when the grade had no rate in force on the date then.
60	     */
61	    public Optional<BigDecimal> rateAsOf(String sheetId, String grade, LocalDate date, LocalDate asOf) {
62	        List<Rate> now = rates.findBySheetIdAndGrade(sheetId, grade);
63	        List<RateLog> set = logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade);
64	        Map<LocalDate, RateLog> then = new LinkedHashMap<>();
65	        for (RateLog log : set) {
66	            if (!log.getSetOn().isAfter(asOf)) {
67	                then.put(log.getFromDate(), log);
68	            }
69	        }
70	        List<Rate> stood = new ArrayList<>();
71	        for (Rate rate : now) {
72	            boolean logged = set.stream().anyMatch(l -> Objects.equals(l.getFromDate(), rate.getFromDate()));
73	            if (!logged) {
74	                stood.add(rate);
75	            }
76	        }
77	        for (RateLog log : then.values()) {
78	            Rate rate = new Rate(sheetId, grade, log.getFromDate(), log.getPct());
79	            rate.setToDate(log.getToDate());
80	            stood.add(rate);
81	        }
82	        return stood.stream()
83	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
84	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
85	                .filter(r -> r.appliesOn(date))
86	                .map(Rate::getPct);
87	    }
88	
89	    /** What the grade having the percent on every date would change on the sheet; nothing is saved. */
90	    @Transactional(readOnly = true)
91	    public RollupService.RatePreview preview(String sheetId, String grade, BigDecimal pct) {
92	        if (!sheets.existsById(sheetId)) {
93	            throw new SheetNotFoundException(sheetId);
94	        }
95	        return rollup.preview(sheetId, grade, pct);
96	    }
97	
98	    /**
99	     * Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null: no
100	     * end), replacing the one it had; a to-date before the from-date is refused.
101	     */
102	    @Transactional
103	    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
104	        if (!sheets.existsById(sheetId)) {
105	            throw new SheetNotFoundException(sheetId);
106	        }
107	        if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
108	            throw new RateDatesException(fromDate, toDate);
109	        }
110	        RollupService.Snapshot before = rollup.snapshot(sheetId);
111	        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
112	        if (rate == null) {
113	            rate = new Rate(sheetId, grade, fromDate, pct);
114	        } else {
115	            rate.setPct(pct);
116	        }
117	        rate.setToDate(toDate);
118	        Rate saved;
119	        try {
120	            saved = rates.saveAndFlush(rate);
121	        } catch (DataIntegrityViolationException e) {
122	            throw new RateTakenException(sheetId, grade);
123	        }
124	        logs.save(new RateLog(saved, sheets.findById(sheetId).orElseThrow().getToday()));
