        for (RateLog log : rateLogs.findBySheetIdOrderByIdAsc(sheetId)) {
            set.computeIfAbsent(log.getGrade(), g -> new ArrayList<>()).add(log);
            now.computeIfAbsent(log.getGrade(), g -> new ArrayList<>());
